var _markdown = "\n\n# Form Integration [#form-integration]\n\n## Formik Integration [#formik-integration]\n\n### Basic Integration [#basic-integration]\n\n```tsx\nimport { Formik } from 'formik';\nimport * as Yup from 'yup';\nimport { TagInput } from 'react-native-input-tag';\n\nconst validationSchema = Yup.object().shape({\n  skills: Yup.array()\n    .min(1, 'At least one skill is required')\n    .max(5, 'Maximum 5 skills allowed')\n    .of(Yup.string().min(2, 'Skills must be at least 2 characters')),\n});\n\nconst FormikExample = () => (\n  <Formik\n    initialValues={{ skills: { tag: '', tagsArray: [] } }}\n    validationSchema={validationSchema}\n    onSubmit={(values) => console.log(values.skills.tagsArray)}\n  >\n    {({ values, setFieldValue, errors, touched }) => (\n      <View>\n        <TagInput\n          label=\"Skills\"\n          tags={values.skills}\n          updateState={(newTags) => setFieldValue('skills', newTags)}\n          containerStyle={[\n            styles.container,\n            errors.skills && touched.skills && styles.errorContainer\n          ]}\n        />\n        {errors.skills && touched.skills && (\n          <Text style={styles.errorText}>{errors.skills}</Text>\n        )}\n      </View>\n    )}\n  </Formik>\n);\n```\n\n### With Field Array [#with-field-array]\n\n```tsx\nimport { Formik, FieldArray } from 'formik';\n\nconst FieldArrayExample = () => (\n  <Formik\n    initialValues={{\n      technologies: { tag: '', tagsArray: [] },\n      frameworks: { tag: '', tagsArray: [] }\n    }}\n  >\n    {({ values, setFieldValue }) => (\n      <FieldArray\n        name=\"technologies\"\n        render={arrayHelpers => (\n          <>\n            <TagInput\n              label=\"Technologies\"\n              tags={values.technologies}\n              updateState={(newTags) => {\n                setFieldValue('technologies', newTags);\n                arrayHelpers.replace(newTags.tagsArray);\n              }}\n            />\n            <Button\n              title=\"Clear All\"\n              onPress={() => arrayHelpers.remove(0)}\n            />\n          </>\n        )}\n      />\n    )}\n  </Formik>\n);\n```\n\n## React Hook Form Integration [#react-hook-form-integration]\n\n### Basic Integration [#basic-integration-1]\n\n```tsx\nimport { useForm, Controller } from 'react-hook-form';\n\nconst HookFormExample = () => {\n  const { control, handleSubmit } = useForm({\n    defaultValues: {\n      technologies: [],\n    },\n  });\n\n  return (\n    <Controller\n      control={control}\n      name=\"technologies\"\n      rules={{ required: true, minLength: 1 }}\n      render={({ field: { onChange, value }, fieldState: { error } }) => (\n        <View>\n          <TagInput\n            tags={{ tag: '', tagsArray: value }}\n            updateState={(newTags) => onChange(newTags.tagsArray)}\n            containerStyle={[\n              styles.container,\n              error && styles.errorContainer\n            ]}\n          />\n          {error && (\n            <Text style={styles.errorText}>\n              Technologies are required\n            </Text>\n          )}\n        </View>\n      )}\n    />\n  );\n};\n```\n\n### With Validation Schema [#with-validation-schema]\n\n```tsx\nimport { useForm } from 'react-hook-form';\nimport { yupResolver } from '@hookform/resolvers/yup';\nimport * as Yup from 'yup';\n\nconst schema = Yup.object().shape({\n  skills: Yup.array()\n    .min(2, 'At least 2 skills are required')\n    .max(10, 'Maximum 10 skills allowed')\n    .of(\n      Yup.string()\n        .min(2, 'Skills must be at least 2 characters')\n        .matches(/^[a-zA-Z0-9-]+$/, 'Only letters, numbers, and hyphens allowed')\n    ),\n});\n\nconst ValidatedFormExample = () => {\n  const { control, handleSubmit, formState: { errors } } = useForm({\n    resolver: yupResolver(schema),\n    defaultValues: {\n      skills: [],\n    },\n  });\n\n  return (\n    <Controller\n      control={control}\n      name=\"skills\"\n      render={({ field: { onChange, value } }) => (\n        <View>\n          <TagInput\n            tags={{ tag: '', tagsArray: value }}\n            updateState={(newTags) => onChange(newTags.tagsArray)}\n            suggestions={['React', 'TypeScript', 'Node.js']}\n            containerStyle={[\n              styles.container,\n              errors.skills && styles.errorContainer\n            ]}\n          />\n          {errors.skills && (\n            <Text style={styles.errorText}>\n              {errors.skills.message}\n            </Text>\n          )}\n        </View>\n      )}\n    />\n  );\n};\n```\n\n## Custom Form Solution [#custom-form-solution]\n\n```tsx\ninterface FormState {\n  skills: string[];\n  level: string;\n  experience: number;\n}\n\nconst CustomFormExample = () => {\n  const [form, setForm] = useState<FormState>({\n    skills: [],\n    level: 'intermediate',\n    experience: 0,\n  });\n\n  const [errors, setErrors] = useState<Partial<FormState>>({});\n\n  const validateForm = () => {\n    const newErrors: Partial<FormState> = {};\n\n    if (form.skills.length === 0) {\n      newErrors.skills = 'At least one skill is required';\n    }\n\n    if (form.experience < 0) {\n      newErrors.experience = 'Experience cannot be negative';\n    }\n\n    setErrors(newErrors);\n    return Object.keys(newErrors).length === 0;\n  };\n\n  const handleSubmit = () => {\n    if (validateForm()) {\n      // Process form data\n      console.log('Form data:', form);\n    }\n  };\n\n  return (\n    <View>\n      <TagInput\n        tags={{ tag: '', tagsArray: form.skills }}\n        updateState={(newTags) => {\n          setForm(prev => ({\n            ...prev,\n            skills: newTags.tagsArray\n          }));\n          // Clear error when user makes changes\n          if (errors.skills) {\n            setErrors(prev => ({\n              ...prev,\n              skills: undefined\n            }));\n          }\n        }}\n        containerStyle={[\n          styles.container,\n          errors.skills && styles.errorContainer\n        ]}\n      />\n      {errors.skills && (\n        <Text style={styles.errorText}>{errors.skills}</Text>\n      )}\n      \n      <Button\n        title=\"Submit\"\n        onPress={handleSubmit}\n      />\n    </View>\n  );\n};\n\nconst styles = StyleSheet.create({\n  container: {\n    borderWidth: 1,\n    borderColor: '#ccc',\n    borderRadius: 8,\n    padding: 10,\n  },\n  errorContainer: {\n    borderColor: '#dc3545',\n    backgroundColor: '#fff8f8',\n  },\n  errorText: {\n    color: '#dc3545',\n    fontSize: 12,\n    marginTop: 5,\n  },\n});\n```\n";
